(6632472, 990140, 45672, '<td valign="top">Good light and crisp detail.  Well done.</td>', 'Good light and crisp detail.  Well done.', '2012-01-02 22:26:56.000000', NULL, 1),
(6632794, 990151, 141319, '<td valign="top">WOW, I think this is good! Some people may think it is a bit on the dark side, but I like it as it is. Great camera angle to really make the "creature" look menacing.</td>', 'WOW, I think this is good! Some people may think it is a bit on the dark side, but I like it as it is. Great camera angle to really make the "creature" look menacing.', '2012-01-03 08:47:57.000000', NULL, 1),
(6632815, 990028, 141319, '<td valign="top">Excellent image. Love the grey background and the dark edge on top. Great "story", told very simply. Good composition, excellent use of colour. Ilike the use of DOF where the "dead" toy is just oof. I think that works very well. There is really nothing I can suggest you should try differently. Very nice work</td>', 'Excellent image. Love the grey background and the dark edge on top. Great "story", told very simply. Good composition, excellent use of colour. Ilike the use of DOF where the "dead" toy is just oof. I think that works very well. There is really nothing I can suggest you should try differently. Very nice work', '2012-01-03 09:20:02.000000', NULL, 1),
(6632816, 990150, 141319, '<td valign="top">Pictures are supposed to "speak to you" - right? Well I am still giggling :-). Fabulous concept and SO well photographed and perfectly put together with the 2 smaller images on top and the "outcome" large and at the bottom. I hope you win :-)</td>', 'Pictures are supposed to "speak to you" - right? Well I am still giggling :-). Fabulous concept and SO well photographed and perfectly put together with the 2 smaller images on top and the "outcome" large and at the bottom. I hope you win :-)', '2012-01-03 09:20:08.000000', NULL, 1),
(6633074, 990098, 110533, '<td valign="top">Great composition. It is very difficult to distinguish between the toys and the background. They blend perfectly.</td>', 'Great composition. It is very difficult to distinguish between the toys and the background. They blend perfectly.', '2012-01-03 14:56:28.000000', NULL, 1),
(6634188, 990140, 69368, '<td valign="top">really funny!</td>', 'really funny!', '2012-01-04 06:53:38.000000', NULL, 1),
(6634245, 990082, 118154, '<td valign="top">I like this very much but on my screen it is way too light and washed out,needs more contrast.<br/>On second viewing and now think higher of it than at first.Bumped up.</td>', 'I like this very much but on my screen it is way too light and washed out,needs more contrast.On second viewing and now think higher of it than at first.Bumped up.', '2012-01-04 08:17:44.000000', NULL, 1),
