(6636631, 990176, 12611, '<td valign="top">This one had the best silly old time story telling to me. Congrats on the top 10.</td>', 'This one had the best silly old time story telling to me. Congrats on the top 10.', '2012-01-06 08:38:05.000000', NULL, 0),
(6636634, 990197, 12611, '<td valign="top">This is photogracphically splendid- all the high key soft tones. Far be it from me to comment on a shot''s relative placement, but, it was the most emotive of all the shots, and probably could not do any better because it relied not on photography, as splendid as it was, yet on a handwritten note to tell the story. I like to think that I have enough literary savvy to recognize that the note <i>is</i> in fact part of the story, but, in a challenge where cartoon strip style editing is allowed, well, congrats on the top ten anyway. sorry for the long ramble.<br/><br/><i>Message edited by author 2012-01-06 08:44:33.</i></td>', 'This is photogracphically splendid- all the high key soft tones. Far be it from me to comment on a shot''s relative placement, but, it was the most emotive of all the shots, and probably could not do any better because it relied not on photography, as splendid as it was, yet on a handwritten note to tell the story. I like to think that I have enough literary savvy to recognize that the note is in fact part of the story, but, in a challenge where cartoon strip style editing is allowed, well, congrats on the top ten anyway. sorry for the long ramble.', '2012-01-06 08:43:33.000000', '2012-01-06 08:44:33.000000', 0),
